import { BoxGeometry, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Group, Color, SpotLight } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // 1. COLORS & THEME SPEC
  const colorsSpec = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const colors = {
    ink: colorsSpec.ink ?? '#16161d',
    paper: colorsSpec.paper ?? '#e8ecf2',
    accent: colorsSpec.accent ?? '#ff2a38',
    surface: colorsSpec.surface ?? '#0b0b10'
  };

  const accentColor = new Color(colors.accent);
  const paperColor = new Color(colors.paper);
  const surfaceColor = new Color(colors.surface);

  // 2. TEXT DATA BRIDGING
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let quoteStr = "“THE CHRONOGRAPH IS NOT LUSTED FOR ITS UTILITY, BUT FOR THE MACHINED PERFECTION OF ITS MOTION.”";
  let attrStr = "— ATELIER CLIENT, JOURNAL ISSUE 04";

  if (textItems.length > 0) {
    quoteStr = textItems[0].text;
    if (textItems[1]) {
      attrStr = textItems[1].text;
    } else {
      attrStr = "";
    }
  }

  // 3. MAIN CARD CONTAINER (for interactive animation offset)
  const cardGroup = new Group();
  group.add(cardGroup);

  // 4. MACHINED METAL SUBSTRATE (PBR Card)
  const cardWidth = 3.4;
  const cardHeight = 2.1;

  // Back border plane / accent edge
  const borderGeom = new PlaneGeometry(cardWidth + 0.04, cardHeight + 0.04);
  const borderMat = new MeshBasicNodeMaterial({
    color: colors.ink
  });
  const borderMesh = new THREE.Mesh(borderGeom, borderMat);
  borderMesh.position.z = -0.01;
  cardGroup.add(borderMesh);

  // Main Card Body
  const bodyGeom = new BoxGeometry(cardWidth, cardHeight, 0.04);
  const bodyMat = new MeshStandardNodeMaterial({
    color: surfaceColor,
    roughness: 0.52,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.3
  });
  const bodyMesh = new THREE.Mesh(bodyGeom, bodyMat);
  cardGroup.add(bodyMesh);

  // 5. PICTURE INSET (Left Side)
  const imgWidth = 1.1;
  const imgHeight = 1.7;
  const imgGeom = new PlaneGeometry(imgWidth, imgHeight);
  // Default elegant dark material until loaded
  const imgMat = new MeshStandardNodeMaterial({
    color: 0x1a1a24,
    roughness: 0.8,
    metalness: 0.1
  });
  const imgMesh = new THREE.Mesh(imgGeom, imgMat);
  imgMesh.position.set(-0.9, 0, 0.025);
  cardGroup.add(imgMesh);

  // Load configured image asset safely
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.color.setHex(0xffffff);
      imgMat.needsUpdate = true;
    }).catch(() => {});
  }

  // 6. TYPOGRAPHY INSET (Right Side)
  const textContainer = new Group();
  textContainer.position.set(-0.2, 0.4, 0.03);
  cardGroup.add(textContainer);

  const quoteText = ctx.fontAtlas.createText(quoteStr, {
    fontSize: 0.095,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 310,
    letterSpacingPx: 0.5
  });
  textContainer.add(quoteText);

  if (attrStr) {
    const attrText = ctx.fontAtlas.createText(attrStr.toUpperCase(), {
      fontSize: 0.065,
      color: colors.accent,
      align: 'left',
      maxWidthPx: 310,
      letterSpacingPx: 1.2
    });
    attrText.position.y = -0.85;
    textContainer.add(attrText);
  }

  // 7. LOCAL HIGH-END LIGHTING (Accent rim shimmers over metal body)
  const localLight = new SpotLight(colors.accent, 1.4, 6, Math.PI / 4, 0.4, 1);
  localLight.position.set(1.5, 1.5, 1.2);
  localLight.target = bodyMesh;
  cardGroup.add(localLight);
  cardGroup.add(localLight.target);

  // 8. INTERACTIVE BEHAVIORS & GSAP
  let hoverTimeline = null;

  const onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    // Subtlest elegant lift up
    hoverTimeline.to(cardGroup.position, {
      y: 0.15,
      z: 0.08,
      duration: 0.4,
      ease: "power2.out"
    });
    // Border turns accent on focus
    hoverTimeline.to(borderMesh.material.color, {
      r: accentColor.r,
      g: accentColor.g,
      b: accentColor.b,
      duration: 0.3
    }, 0);
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(cardGroup.position, {
      y: 0,
      z: 0,
      duration: 0.4,
      ease: "power2.out"
    });
    hoverTimeline.to(borderMesh.material.color, {
      r: 0,
      g: 0,
      b: 0,
      duration: 0.4
    }, 0);
  };

  const onClick = () => {
    gsap.timeline()
      .to(cardGroup.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.1, ease: "power1.out" })
      .to(cardGroup.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: "back.out(2)" });

    ctx.emit('hub-journal.select', { id: config.id ?? 'quote-panel' });
  };

  // Bind interact handlers safely via userData
  group.userData.handlers = {
    pointerover: onHover,
    pointerout: onHoverOut,
    click: onClick
  };

  // 9. APPLY PRIMITIVES
  const scrollPrimitive = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });

  // 10. CLEANUP
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (scrollPrimitive && typeof scrollPrimitive.cleanup === 'function') {
      scrollPrimitive.cleanup();
    }
    borderGeom.dispose();
    borderMat.dispose();
    bodyGeom.dispose();
    bodyMat.dispose();
    imgGeom.dispose();
    imgMat.dispose();
  };

  return group;
}
